@@ -0,0 +1,45 @@
+import { Hono } from 'hono';
+import { parse } from 'csv-parse/sync';
+
+export const bulkRoutes = new Hono();
+
+bulkRoutes.post('/bulk', async (c) => {
+  const { csv } = await c.req.json();
+  const rows = parse(csv, { columns: true });
+
+  for (const row of rows) {
+    await c.env.DB.prepare(
+      'INSERT INTO candidates (name, email, pipeline_id) VALUES (?, ?, ?)'
+    ).bind(row.name, row.email, row.pipeline_id).run();
+  }
+
+  return c.json({ imported: rows.length });
+});
